      causeSyscall: err.cause ? err.cause.syscall : null
    }));
  }
})();

#!/usr/bin/env node
// Diagnostics: retry the email API health check over ~45s to rule out transient DNS issues.

const urls = [
  'https://agenskill-api.onrender.com/health',
  'https://agenskill.onrender.com/health'
];

const sleep = ms => new Promise(r => setTimeout(r, ms));

(async () => {
  for (let attempt = 1; attempt <= 6; attempt++) {
    const results = [];
    for (const url of urls) {
      try {
        const res = await fetch(url, { signal: AbortSignal.timeout(10000) });
        let body = '';
        try { body = await res.text(); } catch (e) { body = '(unreadable body)'; }
        results.push({ url, status: res.status, body: body.slice(0, 200) });
      } catch (err) {
        const cause = err.cause;
        results.push({ url, error: err.message, cause: cause ? (cause.code || cause.message) : null });
      }
    }
    console.log(JSON.stringify({ attempt, results }));
    if (attempt < 6) await sleep(7000);
  }
})();

